routineArtifact.baseline:
export function normalizeName(value) {
  return value;
}

export function displayName(value) {
  return value == null ? 'Anonymous' : normalizeName(value);
}

routineArtifact.candidate:
export function normalizeName(value) {
  return value.trim();
}

export function displayName(value) {
  return value == null ? 'Anonymous' : normalizeName(value);
}
